from pathlib import Path
import hashlib,json
P=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(f,d):(P/f).write_text(json.dumps(d,indent=2)+'\n')
summary={'asset':'rock-shelf-end','stage':'preparation complete; awaiting root reconciliation/freeze','independentInitial':'../initial.json','independentCriteria':'../criteria.json','proposal':'proposed-native-contract.json','requiredEvidence':'evidence-plan.json','keyFindings':['One true W join at localX-.5 with finite six-point section. No corner turn or second port.','Finite ground X[-.5,.34],Y±.45,Z0; core has closed exposed end atX+.34. Actual dressing reachesX+.359 andZ.449; proposed upper envelope keepsZ<=.45.','All4 historical original source atlases replay exactly: zero differing RGBA pixels; no renderer residual.','Canonical source/packet hashes match dispatch. Actual custom normals, point albedo, shader and shadow-disabled broad symmetric rig measured directly from saved source, replacing original-source flat-normal/material assumptions.','No candidates, derivative approval, brief edits, production/Git/live Blender/device operations or other agents.'],'remaining':['Root freezes reconciled contract and visible criteria.','Fresh editor constructs candidate only after freeze.','Fresh judge must inspect exact candidate packet and independent all4 native/consumer family assemblies before any derivative verdict.'],'defectsInPrepHistory':['First native audit sampled hidden collection and got stale child matrices. Invalid data retained explicitly. Corrected audit enables source collection before dependency-graph measurement. Replay renders were correct and did not need repetition.'],'scopeCheck':'Every written file is under rock-shelf-end/reviews; no source input was changed.'}
write('preparation-summary.json',summary)
commands=json.loads((P/'command-records.json').read_text());commands['commands'].append({'step':'hash-seal-and-local-verification','argv':[commands['environment']['pythonExecutable'],'drivers/seal_preparation.py'],'output':['hash-manifest.json','seal.json'],'note':'Seal manifest excludes only itself and seal.json to avoid circular hashes; includes its driver, all actual preparation inputs/outputs/logs and initial/criteria.'});write('command-records.json',commands)
files=sorted([p for p in P.rglob('*') if p.is_file() and p.name not in ['hash-manifest.json','seal.json']]+[P.parent/'initial.json',P.parent/'criteria.json'])
assert all(p.stat().st_size<100_000_000 for p in files)
assert not any('__pycache__' in p.parts or p.suffix=='.pyc' for p in files)
entries=[{'path':str(p.relative_to(P)) if p.is_relative_to(P) else '../'+p.name,'bytes':p.stat().st_size,'sha256':sha(p)} for p in files]
write('hash-manifest.json',{'asset':'rock-shelf-end','scope':'actual-used preparation source/input/import/evidence closure, all files under own reviews only','files':entries,'totalBytes':sum(e['bytes'] for e in entries)})
write('seal.json',{'asset':'rock-shelf-end','stage':'PREPARATION ONLY; no derivative approval','manifest':'hash-manifest.json','manifestSHA256':sha(P/'hash-manifest.json'),'proposalSHA256':sha(P/'proposed-native-contract.json'),'criteriaSHA256':sha(P.parent/'criteria.json'),'initialSHA256':sha(P.parent/'initial.json'),'evidencePlanSHA256':sha(P/'evidence-plan.json'),'canonicalProjectSHA256':sha(P/'resources/canonical-middle/round-03.blend'),'canonicalPacketSHA256':sha(P/'resources/canonical-middle/packet.json'),'fileCount':len(entries),'totalBytes':sum(e['bytes'] for e in entries)})
for e in entries:
 f=P/e['path'];assert sha(f)==e['sha256'],f
print(json.dumps(json.loads((P/'seal.json').read_text()),indent=2))
